Q: How to use TaskDialog in c# Windows Forms A: <p>Check out Microsoft TechNet article with source <a href="https://social.technet.microsoft.com/wiki/contents/articles/54366.net-core-5-taskdialog-c.aspx" rel="nofollow noreferrer">.NET Core 5 TaskDialog (C#)</a></p>
<p><a href="https://github.com/karenpayneoregon/task-dialog-library" rel="nofollow noreferrer">Dialog library</a></p>
<p><a href="https://i.sstatic.net/WQ6Ir.png" rel="nofollow noreferrer"><img src="https://i.sstatic.net/WQ6Ir.png" alt="enter image description here" /></a></p>
<p>Ask a question</p>
<pre><code>public static bool Question(Form owner, string caption, string heading, string yesText, string noText, DialogResult defaultButton)
{

    TaskDialogButton yesButton = new (yesText) { Tag = DialogResult.Yes };
    TaskDialogButton noButton = new (noText) { Tag = DialogResult.No };

    var buttons = new TaskDialogButtonCollection();

    if (defaultButton == DialogResult.Yes)
    {
        buttons.Add(yesButton);
        buttons.Add(noButton);
    }
    else
    {
        buttons.Add(noButton);
        buttons.Add(yesButton);
    }


    TaskDialogPage page = new ()
    {
        Caption = caption,
        SizeToContent = true,
        Heading = heading,
        Icon = TaskDialogIcon.Information,
        Buttons = buttons
    };

    var result = TaskDialog.ShowDialog(owner, page);

    return (DialogResult)result.Tag == DialogResult.Yes;

}
</code></pre>
<p>Show information</p>
<pre><code>public static void Information(IntPtr owner, string heading, string buttonText = &quot;Ok&quot;)
{

    TaskDialogButton okayButton = new(buttonText);

    TaskDialogPage page = new()
    {
        Caption = &quot;Information&quot;,
        SizeToContent = true,
        Heading = heading,
        //Icon = TaskDialogIcon.Information, -- will invoke a beep
        Buttons = new TaskDialogButtonCollection() { okayButton }
    };

    TaskDialog.ShowDialog(owner, page);

}
</code></pre>
